'use strict';
const AntarSolar=(()=>{
 const roles=[['family','Family'],['friend','Friend'],['partner','Partner'],['work','Work / studies'],['other','Other']];
 const palette=['#d6b77b','#b8a9d0','#8fb8ba','#a6b89b','#cfaaa3','#a9b7d2'];
 const unique=list=>[...new Set((Array.isArray(list)?list:[]).filter(x=>typeof x==='string'&&x))];
 const color=value=>palette.includes(value)?value:palette[0];
 const roleName=p=>{const group=roles.find(x=>x[0]===p?.role)?.[1]||'Other';return p?.roleLabel?(p.role==='other'?p.roleLabel:group+' · '+p.roleLabel):group};
 const time=value=>Number.isFinite(Date.parse(value))?Date.parse(value):null;
 const cutoff=value=>value?time(value.length===10?value+'T23:59:59.999':value):Infinity;
 function stamp(base,now){const prior=time(base?.updatedAt),current=time(now);return new Date(Math.max(current??Date.now(),prior===null?0:prior+1)).toISOString()}
 function personSnapshot(p,savedAt=p.updatedAt||p.createdAt){return{version:1,savedAt,name:p.name||'',role:p.role||'other',roleLabel:p.roleLabel||'',type:p.type==='character'?'character':'person',description:p.description||'',color:color(p.color),archived:p.archived===true}}
 function personAt(p,day=''){const history=Array.isArray(p.versions)&&p.versions.length?p.versions:[personSnapshot(p)];const eligible=day?history.filter(v=>time(v.savedAt)!==null&&time(v.savedAt)<=cutoff(day)):history;const v=eligible.at(-1);return v?{...p,...v,id:p.id,kind:'person'}:null}
 function associations(value){return (Array.isArray(value)?value:[]).filter(x=>x&&typeof x.personId==='string').reduce((out,x)=>out.some(v=>v.personId===x.personId)?out:[...out,{personId:x.personId,moodIds:unique(x.moodIds).slice(0,3),note:typeof x.note==='string'?x.note.slice(0,300):''}],[])}
 function thoughtSnapshot(t,savedAt=t.updatedAt||t.createdAt){return{version:1,savedAt,title:t.title||'',text:t.text||'',bucket:t.bucket||'Unsorted',moodIds:unique(t.moodIds).slice(0,3),associations:associations(t.associations),peopleSnapshots:Array.isArray(t.peopleSnapshots)?t.peopleSnapshots.map(p=>({...p,color:color(p.color)})):[],restoredFrom:t.restoredFrom||null}}
 function thoughtVersions(t){return Array.isArray(t.versions)&&t.versions.length?t.versions.map(v=>({...v,moodIds:unique(v.moodIds),associations:associations(v.associations),peopleSnapshots:Array.isArray(v.peopleSnapshots)?v.peopleSnapshots:[]})):[{...thoughtSnapshot(t),legacy:true}]}
 function thoughtAt(t,day=''){const versions=thoughtVersions(t),eligible=day?versions.filter(v=>time(v.savedAt)!==null&&time(v.savedAt)<=cutoff(day)):versions;const v=eligible.at(-1);return v?{...t,...v,id:t.id,kind:'thought'}:null}
 function saveThought(base,draft,people,now,id){const savedAt=stamp(base,now),refs=associations(draft.associations).map(link=>{const person=people.find(p=>p.id===link.personId)||draft.peopleSnapshots?.find(p=>p.id===link.personId);return person?{id:person.id,name:person.name,role:person.role||'other',roleLabel:person.roleLabel||'',type:person.type||'person',color:color(person.color)}:null}).filter(Boolean);const next={...(base||{}),id:base?.id||id,kind:'thought',title:String(draft.title||'').trim(),text:String(draft.text||'').trim(),bucket:draft.bucket||'Unsorted',moodIds:unique(draft.moodIds).slice(0,3),associations:associations(draft.associations),peopleSnapshots:refs,createdAt:base?.createdAt||savedAt,updatedAt:savedAt,restoredFrom:draft.restoredFrom||null};const history=base?thoughtVersions(base):[];return{...next,versions:[...history,{...thoughtSnapshot(next,savedAt),version:history.length+1}]}}
 function savePerson(base,draft,now,id){const savedAt=stamp(base,now),next={...(base||{}),...draft,id:base?.id||id,kind:'person',name:draft.name.trim(),role:roles.some(x=>x[0]===draft.role)?draft.role:'other',roleLabel:(draft.roleLabel||'').trim().slice(0,60),type:draft.type==='character'?'character':'person',description:(draft.description||'').trim().slice(0,600),color:color(draft.color),archived:draft.archived===true,createdAt:base?.createdAt||savedAt,updatedAt:savedAt};const history=base?(Array.isArray(base.versions)&&base.versions.length?base.versions:[personSnapshot(base)]):[];return{...next,versions:[...history,{...personSnapshot(next,savedAt),version:history.length+1}]}}
 function view(items,filters={}){const day=filters.day||'',people=items.filter(x=>x.kind==='person').map(p=>personAt(p,day)).filter(Boolean);let thoughts=items.filter(x=>x.kind==='thought').map(t=>thoughtAt(t,day)).filter(Boolean).filter(t=>!filters.mood||t.moodIds.includes(filters.mood)||t.associations.some(a=>a.moodIds.includes(filters.mood))).filter(t=>!filters.person||t.associations.some(a=>a.personId===filters.person));if(filters.role)thoughts=thoughts.filter(t=>t.associations.some(a=>people.some(p=>p.id===a.personId&&p.role===filters.role)));const shownPeople=people.filter(p=>!filters.role||p.role===filters.role);return{thoughts,people:shownPeople,allPeople:people,personCounts:Object.fromEntries(shownPeople.map(p=>[p.id,thoughts.filter(t=>t.associations.some(a=>a.personId===p.id)).length]))}}
 function timeline(items,filters={}){const limit=cutoff(filters.day||'');return items.filter(x=>x.kind==='thought').flatMap(t=>thoughtVersions(t).map(v=>({...v,thoughtId:t.id}))).filter(v=>(!filters.day||(time(v.savedAt)!==null&&time(v.savedAt)<=limit))&&(!filters.person||v.associations.some(a=>a.personId===filters.person))&&(!filters.mood||v.moodIds.includes(filters.mood)||v.associations.some(a=>a.moodIds.includes(filters.mood)))).sort((a,b)=>(time(b.savedAt)||0)-(time(a.savedAt)||0)||b.version-a.version)}
 function personMoodCounts(thoughts,personId){const counts={};for(const t of thoughts){const link=t.associations.find(a=>a.personId===personId);for(const id of unique(link?.moodIds))counts[id]=(counts[id]||0)+1}return Object.entries(counts).map(([id,count])=>({id,count})).sort((a,b)=>b.count-a.count||a.id.localeCompare(b.id))}
 function sameThought(base,draft){if(!base)return false;const normal=x=>JSON.stringify([String(x.title||'').trim(),String(x.text||'').trim(),x.bucket||'Unsorted',unique(x.moodIds).sort(),associations(x.associations).map(a=>({...a,moodIds:[...a.moodIds].sort()})).sort((a,b)=>a.personId.localeCompare(b.personId))]);return normal(thoughtAt(base))===normal(draft)}
 function historyDays(items){const versions=[...timeline(items),...items.filter(x=>x.kind==='person').flatMap(p=>Array.isArray(p.versions)&&p.versions.length?p.versions:[personSnapshot(p)])];return [...new Set(versions.filter(v=>time(v.savedAt)!==null).map(v=>{const d=new Date(v.savedAt);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}))].sort()}
 function historyTimes(items){return [...new Set([...timeline(items),...items.filter(x=>x.kind==='person').flatMap(p=>Array.isArray(p.versions)&&p.versions.length?p.versions:[personSnapshot(p)])].filter(v=>time(v.savedAt)!==null).map(v=>new Date(v.savedAt).toISOString()))].sort()}
 return{historyTimes,historyDays,sameThought,roles,palette,color,roleName,unique,personSnapshot,personAt,thoughtSnapshot,thoughtVersions,thoughtAt,associations,saveThought,savePerson,view,timeline,personMoodCounts};
})();
if(typeof module!=='undefined'&&module.exports)module.exports=AntarSolar;
